/**
 * Interests (index.html #interests, generated by scripts/sync_notion.py): clicking a chip opens its panel (the
 * projects and jobs tagged with that interest) and closes any other; clicking it again closes it. The open interest
 * goes in the address as #interest=<id>, so project pages can link to one (their Interests chips) and it opens on load.
 * Project cards in a panel open in the project pop-up (site-popups.js); job links open the job (resume.js).
 */
(function () {
  "use strict";
  const section = document.getElementById("interests");
  if (!section) return;
  const chips = [...section.querySelectorAll(".in-chip")];

  function show(id, scroll) {
    let opened = null;
    for (const chip of chips) {
      const on = chip.dataset.interest === id && chip.getAttribute("aria-expanded") !== "true";
      chip.setAttribute("aria-expanded", on);
      document.getElementById(chip.getAttribute("aria-controls")).hidden = !on;
      if (on) opened = chip;
    }
    const url = location.pathname + location.search + (opened ? "#interest=" + id : "");
    if (url !== location.pathname + location.search + location.hash) history.replaceState(history.state, "", url);
    if (opened && scroll) section.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  section.addEventListener("click", e => {
    const chip = e.target.closest(".in-chip");
    if (chip) show(chip.dataset.interest, false);
  });

  // #interest=<id>: from a project page's Interests chips, or a shared link.
  function fromHash() {
    const m = location.hash.match(/^#interest=([0-9a-f]{32})$/);
    const chip = m && chips.find(c => c.dataset.interest === m[1]);
    if (chip && chip.getAttribute("aria-expanded") !== "true") show(m[1], true);
  }
  window.addEventListener("hashchange", fromHash);
  fromHash();
})();
